या")}catch(x){say(u)}t.remove()}}menu.addEventListener("click",function(e){var a=e.target.closest("a");if(!a)return;e.preventDefault();var s=a.getAttribute("data-s"),u=encodeURIComponent(pageUrl()),t=encodeURIComponent("क़ुरआन की आयत - EkKhuda.org");if(s==="wa")window.open("https://wa.me/?text="+t+"%20"+u,"_blank","noopener");else if(s==="tg")window.open("https://t.me/share/url?url="+u+"&text="+t,"_blank","noopener");else if(s==="fb")window.open("https://www.facebook.com/sharer/sharer.php?u="+u,"_blank","noopener");else if(s==="cp")copy();else if(s==="ig"){if(navigator.canShare&&navigator.share){blob().then(function(b){var f=new File([b],"GodAlone-"+cur+(b.type==="image/jpeg"?".jpg":".png"),{type:b.type});if(navigator.canShare({files:[f]}))return navigator.share({files:[f],text:"EkKhuda.org"});copy();say("लिंक कॉपी हो गया। इसे Instagram में पेस्ट कीजिए।")}).catch(function(){})}else{copy();say("लिंक कॉपी हो गया। इसे Instagram में पेस्ट कीजिए।")}}menu.hidden=true})})();</script>


