 if(!/^\d+$/.test(v)){r.className='gx-res';r.textContent='पूरी संख्या लिखिए।';return;}
 try{var n=BigInt(v),q=n/19n,m=n%19n;
  if(m===0n){r.className='gx-res';r.innerHTML='<b>✓ 19 से विभाज्य है</b>'+(v.length<40?v+' ÷ 19 = '+q.toString():'');}
  else{r.className='gx-res no';r.innerHTML='<b>19 से विभाज्य नहीं</b>शेषफल '+m.toString();}
 }catch(e){r.textContent='संख्या बहुत लंबी है।';}}
if(i){i.addEventListener('input',go);go();}
var m=document.getElementById('gxMore'),mb=document.getElementById('ghMenuBtn');
if(m&&mb)m.addEventListener('click',function(){mb.click();});
})();</script>
